  { id: 'rice',    kind: 'station', gives: 'rice',    x: 92,  y: 240, label: 'NASI' },
  { id: 'noodle',  kind: 'station', gives: 'noodle',  x: 92,  y: 360, label: 'MIE' },
  { id: 'chicken', kind: 'station', gives: 'chicken', x: 92,  y: 480, label: 'AYAM' },
