// Warm hawker-stall palette; every drawing in render.js uses these.
export const COLORS = {
  floorA: '#e8c99a',
  floorB: '#dfc08a',
  wall: '#8a5a33',
  counter: '#a06a3b',
  counterTop: '#c98d54',
  board: '#e9dcc3',
  wok: '#3a3a3f',
  wokHot: '#e25822',
  plate: '#f7f3e8',
  pass: '#f2e3c6',
  ink: '#2b1d12',
  cream: '#fff6e0',
  red: '#c0392b',
  green: '#5b8c4a',
  gold: '#f2c14e',
  ticket: '#fff8e7',
